1	import {
2	  Client,
3	  GatewayIntentBits,
4	  Events,
5	  ChannelType,
6	  WebhookClient,
7	  ButtonBuilder,
8	  ActionRowBuilder,
9	  ButtonStyle,
10	  SlashCommandBuilder,
11	  MessageFlags,
12	} from "discord.js";
13	import type {
14	  TextChannel,
15	  CategoryChannel,
16	  Interaction,
17	} from "discord.js";
18	import {
19	  getRoster,
20	  findAgent,
21	  findAgentByName,
22	  buildSystemPrompt,
23	  readFileSafe,
24	  type Agent,
25	} from "./roster";
26	import { askAgent, buildTranscript } from "./inference";
27	import { DEFAULT_LEVEL, COS_REGISTER_PATH } from "./config";
28	import { trunc } from "./util";
29	import { runAgentTask, type TaskEvent } from "./executor";
30	import { makeCanUseTool, type Approver } from "./approval";
31	import {
32	  createTask,
33	  appendEvent,
34	  setStatus,
35	  finishTask,
36	  failTask,
37	  listRecent,
38	} from "./tasks";
39	import {
40	  isAutopilot,
41	  isAlwaysAllowed,
42	  isDangerous,
43	  toggleAutopilot,
44	  alwaysAllow,
45	} from "./autopilot";
46	
47	const GUILD_ID = process.env.DISCORD_GUILD_ID ?? "";
48	const DISCORD_MAX = 1900; // stay under Discord's 2000-char message limit
49	
50	// channelId ↔ agentId, plus per-channel webhook (for posting as the agent)
51	const channelToAgent = new Map<string, string>();
52	const agentToChannel = new Map<string, string>();
53	const webhookCache = new Map<string, WebhookClient>();
54	const pendingApprovals = new Map<
55	  string,
56	  { resolve: (ok: boolean) => void; channelId: string; messageId: string; tool: string; agentId: string }
57	>();
58	let taskSeq = 0;
59	let botClient: Client; // set in startDiscord; used by delegation to reach other channels
60	
61	function slug(s: string): string {
62	  return (
63	    s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 90) || "x"
64	  );
65	}
66	
67	function chunkText(s: string, n: number): string[] {
68	  if (!s) return ["(empty)"];
69	  const out: string[] = [];
70	  for (let i = 0; i < s.length; i += n) out.push(s.slice(i, i + n));
71	  return out;
72	}
73	
74	const STATUS_EMOJI: Record<string, string> = {
75	  running: "🟡",
76	  "awaiting-approval": "⏸️",
77	  done: "✅",
78	  error: "❌",
79	};
80	
81	/** Ensure a category per project and a channel per agent; (re)build the id maps. */
82	async function ensureStructure(client: Client): Promise<void> {
83	  const guild = await client.guilds.fetch(GUILD_ID);
84	  const existing = await guild.channels.fetch();
85	
86	  for (const project of getRoster()) {
87	    const catName = slug(project.name);
88	    let category =
89	      (existing.find(
90	        (c) => c?.type === ChannelType.GuildCategory && c.name === catName
91	      ) as CategoryChannel | undefined) ?? undefined;
92	    if (!category) {
93	      category = await guild.channels.create({
94	        name: catName,
95	        type: ChannelType.GuildCategory,
96	      });
97	    }
98	
99	    for (const agent of project.agents) {
100	      const chName = slug(agent.name);
101	      let channel =
102	        (existing.find(
103	          (c) =>
104	            c?.type === ChannelType.GuildText &&
105	            c.name === chName &&
106	            c.parentId === category!.id
107	        ) as TextChannel | undefined) ?? undefined;
108	      if (!channel) {
109	        channel = await guild.channels.create({
110	          name: chName,
111	          type: ChannelType.GuildText,
112	          parent: category.id,
113	          topic: `${agent.title} — type a task to run it; /ask for a quick answer.`,
114	        });
115	      }
116	      channelToAgent.set(channel.id, agent.id);
117	      agentToChannel.set(agent.id, channel.id);
118	    }
119	  }
120	}
121	
122	/** A cached webhook for a channel so an agent can post under its own name. */
123	async function getWebhook(channel: TextChannel): Promise<WebhookClient> {
124	  const cached = webhookCache.get(channel.id);
125	  if (cached) return cached;
126	  const hooks = await channel.fetchWebhooks();
127	  let hook = hooks.find((h) => h.name === "LifeOS" && Boolean(h.token));
128	  if (!hook) hook = await channel.createWebhook({ name: "LifeOS" });
129	  const wc = new WebhookClient({ id: hook.id, token: hook.token! });
130	  webhookCache.set(channel.id, wc);
131	  return wc;
132	}
133	
134	/** Low-level: post via the agent's webhook, returning the message id. */
135	async function sendAsAgent(
136	  channel: TextChannel,
137	  agent: Agent,
138	  payload: { content: string; components?: ActionRowBuilder<ButtonBuilder>[] }
139	): Promise<string> {
140	  const wh = await getWebhook(channel);
141	  const msg = await wh.send({
142	    username: agent.title,
143	    avatarURL: agent.avatarUrl,
144	    content: payload.content,
145	    components: payload.components,
146	  });
147	  return msg.id;
148	}
149	
150	/** Edit a prior webhook message in-place (used by the throttled render loop). */
151	async function editAsAgent(
152	  channel: TextChannel,
153	  messageId: string,
154	  payload: { content: string; components?: ActionRowBuilder<ButtonBuilder>[] }
155	): Promise<void> {
156	  const wh = await getWebhook(channel);
157	  await wh.editMessage(messageId, payload).catch(() => {});
158	}
159	
160	/** Post a (possibly chunked) message that appears to come from the agent itself. */
161	async function postAsAgent(channel: TextChannel, agent: Agent, content: string): Promise<void> {
162	  for (const part of chunkText(content, DISCORD_MAX)) {
163	    await sendAsAgent(channel, agent, { content: part });
164	  }
165	}
166	
167	function approvalRow(id: string): ActionRowBuilder<ButtonBuilder> {
168	  return new ActionRowBuilder<ButtonBuilder>().addComponents(
169	    new ButtonBuilder().setCustomId(`approve:${id}`).setLabel("Approve").setStyle(ButtonStyle.Success),
170	    new ButtonBuilder().setCustomId(`always:${id}`).setLabel("Always (this tool)").setStyle(ButtonStyle.Primary),
171	    new ButtonBuilder().setCustomId(`deny:${id}`).setLabel("Deny").setStyle(ButtonStyle.Danger)
172	  );
173	}
174	
175	/** Run a task in an agent's channel: stream activity, gate tools, post the result as the agent. */
176	async function runTaskInChannel(
177	  channel: TextChannel,
178	  agent: Agent,
179	  prompt: string,
180	  canDelegate = true
181	): Promise<string> {
182	  const taskId = `task_${Date.now()}_${taskSeq++}`;
183	  createTask({ id: taskId, agentId: agent.id, agentTitle: agent.title, user: "discord", prompt });
184	
185	  const activityId = await sendAsAgent(channel, agent, {
186	    content: `🟡 **${agent.title}** is working…`,
187	  });
188	  const lines: string[] = [];
189	  let lastEdit = 0;
190	
191	  const render = async (done: boolean, force = false): Promise<void> => {
192	    const now = Date.now();
193	    if (!force && !done && now - lastEdit < 1500) return; // throttle edits (Discord rate limits)
194	    lastEdit = now;
195	    const head = done ? `✅ **${agent.title}** — done` : `🟡 **${agent.title}** is working…`;
196	    await editAsAgent(channel, activityId, {
197	      content: trunc(`${head}\n${lines.join("\n") || "_starting…_"}`, DISCORD_MAX),
198	    });
199	  };
200	
201	  const onEvent = async (e: TaskEvent): Promise<void> => {
202	    if (e.kind === "tool") {
203	      lines.push(`${e.delegated ? "↳ " : "🔧 "}${e.summary}`);
204	      appendEvent(taskId, "tool", e.summary);
205	      await render(false);
206	    } else if (e.kind === "text") {
207	      appendEvent(taskId, "text", e.text);
208	    } else if (e.kind === "result") {
209	      appendEvent(taskId, "result", `${e.turns} turns · $${e.costUsd.toFixed(4)}`);
210	    } else if (e.kind === "error") {
211	      lines.push(`⚠️ ${e.message}`);
212	      appendEvent(taskId, "error", e.message);
213	      await render(false, true);
214	    }
215	  };
216	
217	  const approver: Approver = async (req) => {
218	    // Autopilot / "always allow": act without asking — except destructive/outbound actions.
219	    if (
220	      (isAutopilot(agent.id) || isAlwaysAllowed(agent.id, req.tool)) &&
221	      !isDangerous(req.tool, req.summary)
222	    ) {
223	      lines.push(`✅ auto-approved ${req.tool}`);
224	      appendEvent(taskId, "tool", `auto-approved ${req.tool}`);
225	      await render(false);
226	      return true;
227	    }
228	    return new Promise<boolean>((resolve) => {
229	      setStatus(taskId, "awaiting-approval");
230	      sendAsAgent(channel, agent, {
231	        content: `⏸️ **${agent.title}** wants to run **${req.tool}**\n\`${trunc(req.summary, 300)}\``,
232	        components: [approvalRow(req.id)],
233	      })
234	        .then((msgId) => {
235	          pendingApprovals.set(req.id, {
236	            resolve,
237	            channelId: channel.id,
238	            messageId: msgId,
239	            tool: req.tool,
240	            agentId: agent.id,
241	          });
242	        })
243	        .catch(() => resolve(false));
244	    }).then((ok) => {
245	      setStatus(taskId, "running");
246	      return ok;
247	    });
248	  };
249	
250	  // Orchestrators (the CoS) can delegate: the target agent runs in ITS OWN channel,
251	  // as itself, as its own task, and its result comes back here. Delegates can't
252	  // re-delegate (canDelegate=false) so there's no infinite delegation.
253	  const onDelegate =
254	    agent.isOrchestrator && canDelegate
255	      ? async (agentKey: string, task: string): Promise<string> => {
256	          const target = findAgent(agentKey) ?? findAgentByName(agentKey);
257	          if (!target) return `No agent matching "${agentKey}".`;
258	          const chId = agentToChannel.get(target.id);
259	          const tch = chId
260	            ? ((await botClient.channels.fetch(chId).catch(() => null)) as TextChannel | null)
261	            : null;
262	          if (!tch) return `No channel for ${target.id}.`;
263	          return runTaskInChannel(tch, target, `[Delegated by ${agent.title}]\n${task}`, false);
264	        }
265	      : undefined;
266	
267	  try {
268	    const { result, costUsd } = await runAgentTask({
269	      agent,
270	      prompt,
271	      onEvent,
272	      canUseTool: makeCanUseTool(approver),
273	      onDelegate,
274	    });
275	    finishTask(taskId, result, costUsd);
276	    await render(true, true);
277	    await postAsAgent(channel, agent, result || "(no result)");
278	    return result || "";
279	  } catch (e: any) {
280	    failTask(taskId, e?.message ?? String(e));
281	    await sendAsAgent(channel, agent, {
282	      content: `❌ Task failed: ${e?.message ?? String(e)}`,
283	    });
284	    return `Task failed: ${e?.message ?? String(e)}`;
285	  }
286	}
287	
288	async function handleInteraction(client: Client, interaction: Interaction): Promise<void> {
289	  if (interaction.isButton()) {
290	    const [action, id] = interaction.customId.split(":");
291	    const pending = pendingApprovals.get(id);
292	    // Ack the click first; a webhook-authored message can't be edited via
293	    // interaction.update(), so we edit it out-of-band through the webhook.
294	    await interaction.deferUpdate().catch(() => {});
295	    if (pending) {
296	      pendingApprovals.delete(id);
297	      if (action === "always") alwaysAllow(pending.agentId, pending.tool);
298	      pending.resolve(action !== "deny");
299	      const ch = (await client.channels.fetch(pending.channelId).catch(() => null)) as TextChannel | null;
300	      const agentId = ch ? channelToAgent.get(ch.id) : undefined;
301	      const agent = agentId ? findAgent(agentId) : undefined;
302	      if (ch && agent) {
303	        const label =
304	          action === "deny"
305	            ? "🚫 Denied"
306	            : action === "always"
307	              ? `✅ Approved — won't ask again for ${pending.tool}`
308	              : "✅ Approved";
309	        await editAsAgent(ch, pending.messageId, { content: label, components: [] });
310	      }
311	    }
312	    return;
313	  }
314	  if (!interaction.isChatInputCommand()) return;
315	
316	  if (interaction.commandName === "agents") {
317	    const lines = getRoster().flatMap((p) => [
318	      `**${p.name}**`,
319	      ...p.agents.map((a) => `• ${a.title} → <#${agentToChannel.get(a.id) ?? ""}>`),
320	    ]);
321	    await interaction.reply({ content: trunc(lines.join("\n"), DISCORD_MAX), flags: MessageFlags.Ephemeral });
322	  } else if (interaction.commandName === "ask") {
323	    const q = interaction.options.getString("question", true);
324	    const agent = findAgent(channelToAgent.get(interaction.channelId) ?? "");
325	    if (!agent) {
326	      await interaction.reply({ content: "Use `/ask` inside an agent's channel.", flags: MessageFlags.Ephemeral });
327	      return;
328	    }
329	    await interaction.deferReply();
330	    const reply = await askAgent(
331	      buildSystemPrompt(agent),
332	      buildTranscript([], q),
333	      DEFAULT_LEVEL
334	    ).catch((e: any) => `⚠️ ${e?.message ?? String(e)}`);
335	    await interaction.editReply(trunc(reply || "(no response)", DISCORD_MAX));
336	  } else if (interaction.commandName === "status") {
337	    const md = readFileSafe(COS_REGISTER_PATH, "(no register found)");
338	    await interaction.reply({
339	      content: trunc("```\n" + md + "\n```", DISCORD_MAX),
340	      flags: MessageFlags.Ephemeral,
341	    });
342	  } else if (interaction.commandName === "tasks") {
343	    const recent = listRecent(10);
344	    const body = recent.length
345	      ? recent
346	          .map((t) => `${STATUS_EMOJI[t.status] ?? "•"} ${t.agentTitle} — ${t.status}: ${trunc(t.prompt, 60)}`)
347	          .join("\n")
348	      : "_No tasks yet._";
349	    await interaction.reply({ content: trunc(body, DISCORD_MAX), flags: MessageFlags.Ephemeral });
350	  } else if (interaction.commandName === "setup") {
351	    await interaction.deferReply({ flags: MessageFlags.Ephemeral });
352	    await ensureStructure(client);
353	    await interaction.editReply(`Created/verified ${agentToChannel.size} agent channels.`);
354	  } else if (interaction.commandName === "autopilot") {
355	    const agent = findAgent(channelToAgent.get(interaction.channelId) ?? "");
356	    if (!agent) {
357	      await interaction.reply({ content: "Use `/autopilot` inside an agent's channel.", flags: MessageFlags.Ephemeral });
358	      return;
359	    }
360	    const on = toggleAutopilot(agent.id);
361	    await interaction.reply({
362	      content: on
363	        ? `🛫 Autopilot **ON** for **${agent.title}** — it will act without asking, except destructive/outbound actions (rm -rf, git push, sudo, outbound POST…), which still confirm.`
364	        : `🛑 Autopilot **OFF** for **${agent.title}** — it will ask before each gated action.`,
365	      flags: MessageFlags.Ephemeral,
366	    });
367	  }
368	}
369	
370	async function registerCommands(client: Client): Promise<void> {
371	  const guild = await client.guilds.fetch(GUILD_ID);
372	  await guild.commands.set([
373	    new SlashCommandBuilder().setName("agents").setDescription("List your agents and their channels").toJSON(),
374	    new SlashCommandBuilder()
375	      .setName("ask")
376	      .setDescription("Quick answer from this channel's agent (no tools)")
377	      .addStringOption((o) => o.setName("question").setDescription("Your question").setRequired(true))
378	      .toJSON(),
379	    new SlashCommandBuilder().setName("tasks").setDescription("Recent task instances").toJSON(),
380	    new SlashCommandBuilder().setName("status").setDescription("Chief of Staff status register").toJSON(),
381	    new SlashCommandBuilder().setName("setup").setDescription("Create/verify the agent channel structure").toJSON(),
382	    new SlashCommandBuilder()
383	      .setName("autopilot")
384	      .setDescription("Toggle autonomous mode for this channel's agent (still confirms destructive actions)")
385	      .toJSON(),
386	  ]);
387	}
388	
389	/** Start the Discord frontend. */
390	export function startDiscord(): Client {
391	  const client = new Client({
392	    intents: [
393	      GatewayIntentBits.Guilds,
394	      GatewayIntentBits.GuildMessages,
395	      GatewayIntentBits.MessageContent,
396	    ],
397	  });
398	  botClient = client;
399	
400	  client.once(Events.ClientReady, async (c) => {
401	    try {
402	      await ensureStructure(c);
403	      await registerCommands(c);
404	      console.log(
405	        `⚡️ LifeOS Discord console ready as ${c.user.tag} — ${agentToChannel.size} agent channels.`
406	      );
407	    } catch (e: any) {
408	      console.error("Startup error:", e?.message ?? e);
409	    }
410	  });
411	
412	  // A message in an agent's channel = run that agent as a task.
413	  client.on(Events.MessageCreate, async (msg) => {
414	    if (msg.author.bot || msg.webhookId) return;
415	    const agentId = channelToAgent.get(msg.channelId);
416	    if (!agentId) return;
417	    const text = msg.content.trim();
418	    if (!text) return;
419	    const agent = findAgent(agentId);
420	    if (agent) await runTaskInChannel(msg.channel as TextChannel, agent, text);
421	  });
422	
423	  client.on(Events.InteractionCreate, (interaction) => {
424	    handleInteraction(client, interaction).catch((e) => console.error("interaction error:", e));
425	  });
426	
427	  client.login(process.env.DISCORD_BOT_TOKEN);
428	  return client;
429	}
