import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadJson, saveJson } from "./util";

export interface Turn {
  role: "user" | "assistant";
  text: string;
}

interface UserState {
  activeAgentId?: string;
  histories: Record<string, Turn[]>; // agentId -> turns
}

interface StoreShape {
  users: Record<string, UserState>;
}

const DATA_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", ".data");
const STORE_PATH = path.join(DATA_DIR, "store.json");

const MAX_TURNS = 20;

let store: StoreShape = loadJson<StoreShape>(STORE_PATH, { users: {} });

function save(): void {
  saveJson(STORE_PATH, store);
}

function userState(user: string): UserState {
  return (store.users[user] ??= { histories: {} });
}

export function getActive(user: string): string | undefined {
  return userState(user).activeAgentId;
}

export function setActive(user: string, agentId: string): void {
  userState(user).activeAgentId = agentId;
  save();
}

export function getHistory(user: string, agentId: string): Turn[] {
  return (userState(user).histories[agentId] ??= []);
}

export function appendTurn(
  user: string,
  agentId: string,
  role: Turn["role"],
  text: string
): void {
  const h = getHistory(user, agentId);
  h.push({ role, text });
  if (h.length > MAX_TURNS) {
    userState(user).histories[agentId] = h.slice(-MAX_TURNS);
  }
  save();
}

