import type { CanUseTool, PermissionResult } from "@anthropic-ai/claude-agent-sdk";
import { summarizeTool } from "./agentConfig";

export interface ApprovalRequest {
  id: string;
  tool: string;
  summary: string;
}

export type Approver = (req: ApprovalRequest) => Promise<boolean>;

let counter = 0;

/**
 * Build a `canUseTool` handler. Safe tools are already auto-allowed via `allowedTools`,
 * so this is only reached for gated tools (Edit/Write/Bash/Agent/...). Each one is routed
 * to `approve`, which decides (e.g. by asking Nick in Slack).
 */
export function makeCanUseTool(approve: Approver): CanUseTool {
  return async (toolName, input) => {
    const id = `appr_${Date.now()}_${counter++}`;
    const ok = await approve({
      id,
      tool: toolName,
      summary: summarizeTool(toolName, input as Record<string, unknown>),
    });
    const result: PermissionResult = ok
      ? { behavior: "allow", updatedInput: input as Record<string, unknown> }
      : { behavior: "deny", message: `Denied by Nick: ${toolName}` };
    return result;
  };
}

/** Non-interactive default (smoke tests / no Slack): deny every gated tool — safe by construction. */
export const denyAllApprover: Approver = async () => false;

