import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadJson, saveJson } from "./util";

// Per-agent autonomy: when autopilot is on (or a tool is "always allowed"), the
// agent acts without asking — EXCEPT genuinely destructive/outbound actions,
// which stay gated even in autopilot.

const DATA = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  ".data",
  "autopilot.json"
);

interface AutopilotState {
  agents: Record<string, boolean>; // agentId -> autopilot on
  alwaysAllow: Record<string, string[]>; // agentId -> [toolName]
}

let state: AutopilotState = loadJson<AutopilotState>(DATA, { agents: {}, alwaysAllow: {} });
const save = (): void => saveJson(DATA, state);

export function isAutopilot(agentId: string): boolean {
  return state.agents[agentId] === true;
}

export function toggleAutopilot(agentId: string): boolean {
  const next = !isAutopilot(agentId);
  state.agents[agentId] = next;
  save();
  return next;
}

export function isAlwaysAllowed(agentId: string, tool: string): boolean {
  return (state.alwaysAllow[agentId] ?? []).includes(tool);
}

export function alwaysAllow(agentId: string, tool: string): void {
  const list = (state.alwaysAllow[agentId] ??= []);
  if (!list.includes(tool)) {
    list.push(tool);
    save();
  }
}

// Shell commands / actions that ALWAYS require explicit confirmation, even under
// autopilot — irreversible or outbound. Matched against the tool's summary.
const DANGER =
  /\brm\s+-rf|\bgit\s+push|--force\b|\bsudo\b|\bcurl\b[^\n]*-X\s*(POST|PUT|DELETE)|\bnpm\s+publish|\bmkfs\b|\bdd\s+if=/i;

/** True when a gated action is destructive/outbound and must be confirmed regardless of autopilot. */
export function isDangerous(tool: string, summary: string): boolean {
  if (tool === "Bash") return DANGER.test(summary);
  // Edit/Write within the agent's own project are reversible (git-tracked) → fine under autopilot.
  // Delegation (Agent) and reads are not destructive. Only shell needs the guard above.
  return false;
}

