import fs from "node:fs";
import path from "node:path";

/** Truncate a string, appending `suffix` only when it was cut. */
export function trunc(s: string, n: number, suffix = "…"): string {
  return s.length > n ? s.slice(0, n) + suffix : s;
}

/** Read + parse a JSON file, returning `fallback` on any error. */
export function loadJson<T>(file: string, fallback: T): T {
  try {
    return JSON.parse(fs.readFileSync(file, "utf8")) as T;
  } catch {
    return fallback;
  }
}

/** Write a value as pretty JSON, creating the directory. Best-effort (never throws). */
export function saveJson(file: string, data: unknown): void {
  try {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, JSON.stringify(data, null, 2));
  } catch {
    /* best-effort persistence */
  }
}

