// One-off: verify the Discord bot token logs in, list its servers, then exit.
//   npx tsx scripts/discord-verify.ts
import "dotenv/config";
import { Client, GatewayIntentBits, Events } from "discord.js";

const token = process.env.DISCORD_BOT_TOKEN;
if (!token) {
  console.error("no DISCORD_BOT_TOKEN in .env");
  process.exit(1);
}

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

const bail = setTimeout(() => {
  console.error("TIMEOUT: never reached ready (check token / intents)");
  process.exit(1);
}, 20000);

client.once(Events.ClientReady, async (c) => {
  clearTimeout(bail);
  console.log("READY as", c.user.tag, "(id " + c.user.id + ")");
  const guilds = c.guilds.cache.map((g) => `${g.name}  ->  DISCORD_GUILD_ID=${g.id}`);
  console.log("intents OK (incl. MESSAGE CONTENT)");
  console.log("servers:", guilds.length ? "\n  " + guilds.join("\n  ") : "(none — bot not invited to any server yet)");
  await c.destroy();
  process.exit(0);
});

client.login(token).catch((e) => {
  clearTimeout(bail);
  console.error("LOGIN FAILED:", e?.message ?? String(e));
  process.exit(1);
});

