199	    const convoId: string = msg.channelId;
200	    // A pending ask_user question takes the next reply instead of starting a task.
201	    const pendingQ = pendingQuestions.get(convoId);
202	    if (pendingQ) {
203	      pendingQuestions.delete(convoId);
204	      pendingQ(text);
205	      return;
206	    }
207	
208	    const sendable = asSendable(msg.channel);
209	    if (!sendable) return;
210	    const sessionKey = isDM
211	      ? dmKey(this.agent.id, msg.author.id)
212	      : channelKey(this.agent.id, convoId);
213	    await this.runTask(sendable, text, sessionKey, convoId);
214	  }
215	
216	  /** Run this agent as a task in `sendable`, resuming `sessionKey` so the thread remembers. */
217	  async runTask(
218	    sendable: Sendable,
219	    prompt: string,
220	    sessionKey: string,
221	    convoId: string,
222	    canDelegate = true
223	  ): Promise<string> {
224	    const agent = this.agent;
225	    const taskId = `task_${Date.now()}_${taskSeq++}`;
226	    createTask({ id: taskId, agentId: agent.id, agentTitle: agent.title, user: "discord", prompt });
227	
228	    const activity = await sendable
229	      .send({ content: `🟡 **${agent.title}** is working…` })
230	      .catch(() => null);
231	    const lines: string[] = [];
232	    let lastEdit = 0;
233	
234	    const render = async (done: boolean, force = false): Promise<void> => {
235	      if (!activity) return;
236	      const now = Date.now();
237	      if (!force && !done && now - lastEdit < 1500) return; // throttle edits
238	      lastEdit = now;
239	      const head = done ? `✅ **${agent.title}** — done` : `🟡 **${agent.title}** is working…`;
240	      await activity
241	        .edit({ content: trunc(`${head}\n${lines.join("\n") || "_starting…_"}`, DISCORD_MAX) })
242	        .catch(() => {});
243	    };
244	
245	    const onEvent = async (e: TaskEvent): Promise<void> => {
246	      if (e.kind === "tool") {
247	        lines.push(`${e.delegated ? "↳ " : "🔧 "}${e.summary}`);
248	        appendEvent(taskId, "tool", e.summary);
249	        await render(false);
250	      } else if (e.kind === "text") {
251	        appendEvent(taskId, "text", e.text);
252	      } else if (e.kind === "result") {
253	        appendEvent(taskId, "result", `${e.turns} turns · $${e.costUsd.toFixed(4)}`);
254	      } else if (e.kind === "error") {
255	        lines.push(`⚠️ ${e.message}`);
256	        appendEvent(taskId, "error", e.message);
257	        await render(false, true);
258	      }
259	    };
260	
261	    const approver: Approver = async (req) => {
262	      // Memory writes are always reviewed, even under autopilot — they change the agent's definition.
263	      const alwaysConfirm = req.tool === MEMORY_TOOL_NAME;
264	      if (
265	        !alwaysConfirm &&
266	        (isAutopilot(agent.id) || isAlwaysAllowed(agent.id, req.tool)) &&
267	        !isDangerous(req.tool, req.summary)
268	      ) {
269	        lines.push(`✅ auto-approved ${req.tool}`);
270	        appendEvent(taskId, "tool", `auto-approved ${req.tool}`);
271	        await render(false);
272	        return true;
273	      }
274	      return new Promise<boolean>((resolve) => {
275	        setStatus(taskId, "awaiting-approval");
276	        sendable
277	          .send({
278	            content: `⏸️ **${agent.title}** wants to run **${req.tool}**\n\`${trunc(req.summary, 300)}\``,
279	            components: [approvalRow(req.id)],
280	          })
281	          .then(() => {
282	            pendingApprovals.set(req.id, { resolve, tool: req.tool, agentId: agent.id });
283	          })
284	          .catch(() => resolve(false));
285	      }).then((ok) => {
286	        setStatus(taskId, "running");
287	        return ok;
288	      });
289	    };
290	
291	    // ISC-9: the agent can pause and ask Nick a free-form question; the next reply answers it.
292	    const onAskUser = async (question: string): Promise<string> => {
293	      await sendable
294	        .send({ content: `❓ **${agent.title}** asks:\n${trunc(question, DISCORD_MAX - 40)}` })
295	        .catch(() => {});
296	      return new Promise<string>((resolve) => {
297	        pendingQuestions.set(convoId, resolve);
298	      });
299	    };
300	
301	    // Orchestrators delegate: the target agent runs in ITS OWN channel, as its own bot.
302	    const onDelegate =
303	      agent.isOrchestrator && canDelegate
304	        ? async (agentKey: string, task: string): Promise<string> => {
305	            const target = findAgent(agentKey) ?? findAgentByName(agentKey);
306	            if (!target) return `No agent matching "${agentKey}".`;
307	            const tbot = bots.get(target.id);
308	            if (!tbot) return `${target.title} has no bot configured (no Discord token).`;
309	            return tbot.runInOwnChannel(`[Delegated by ${agent.title}]\n${task}`);
310	          }
311	        : undefined;
312	
313	    try {
314	      const { result, costUsd, sessionId } = await runAgentTask({
315	        agent,
316	        prompt,
317	        onEvent,
318	        canUseTool: makeCanUseTool(approver),
319	        onDelegate,
320	        onAskUser,
321	        resume: getSession(sessionKey),
322	      });
323	      setSession(sessionKey, sessionId); // ISC-7: remember the session for next time
324	      finishTask(taskId, result, costUsd);
325	      await render(true, true);
326	      for (const part of chunkText(result || "(no result)", DISCORD_MAX)) {
327	        await sendable.send({ content: part }).catch(() => {});
328	      }
329	      return result || "";
330	    } catch (e: any) {
331	      failTask(taskId, e?.message ?? String(e));
332	      await sendable.send({ content: `❌ Task failed: ${e?.message ?? String(e)}` }).catch(() => {});
333	      return `Task failed: ${e?.message ?? String(e)}`;
334	    }
335	  }
336	
337	  /** Run a (delegated) task in this agent's own channel. */
338	  async runInOwnChannel(prompt: string): Promise<string> {
339	    if (!this.channelId) return `${this.agent.title} has no channel yet.`;
340	    const ch = await this.client.channels.fetch(this.channelId).catch(() => null);
341	    const sendable = asSendable(ch);
342	    if (!sendable) return `${this.agent.title}'s channel is unreachable.`;
343	    return this.runTask(
344	      sendable,
345	      prompt,
346	      channelKey(this.agent.id, this.channelId),
347	      this.channelId,
348	      false
349	    );
350	  }
351	
352	  private async onInteraction(interaction: Interaction): Promise<void> {
353	    if (interaction.isButton()) {
354	      const [action, id] = interaction.customId.split(":");
355	      const pending = pendingApprovals.get(id);
356	      if (!pending) {
357	        await interaction.deferUpdate().catch(() => {});
358	        return;
359	      }
360	      pendingApprovals.delete(id);
361	      if (action === "always") alwaysAllow(pending.agentId, pending.tool);
362	      pending.resolve(action !== "deny");
363	      const label =
364	        action === "deny"
365	          ? "🚫 Denied"
366	          : action === "always"
367	            ? `✅ Approved — won't ask again for ${pending.tool}`
368	            : "✅ Approved";
369	      // This bot authored the message, so a direct interaction.update() works (no webhook hack).
370	      await interaction.update({ content: label, components: [] }).catch(() => {});
371	      return;
372	    }
373	    if (!interaction.isChatInputCommand()) return;
374	    const agent = this.agent;
375	
376	    if (interaction.commandName === "ask") {
377	      const q = interaction.options.getString("question", true);
378	      await interaction.deferReply();
379	      const reply = await askAgent(buildSystemPrompt(agent), buildTranscript([], q), DEFAULT_LEVEL).catch(
380	        (e: any) => `⚠️ ${e?.message ?? String(e)}`
381	      );
382	      await interaction.editReply(trunc(reply || "(no response)", DISCORD_MAX));
383	    } else if (interaction.commandName === "autopilot") {
384	      const on = toggleAutopilot(agent.id);
385	      await interaction.reply({
386	        content: on
387	          ? `🛫 Autopilot **ON** for **${agent.title}** — I act without asking, except destructive/outbound actions (and memory writes), which still confirm.`
388	          : `🛑 Autopilot **OFF** for **${agent.title}** — I ask before each gated action.`,
389	        flags: MessageFlags.Ephemeral,
390	      });
391	    } else if (interaction.commandName === "tasks") {
392	      const recent = listRecent(10);
393	      const body = recent.length
394	        ? recent
395	            .map((t) => `${STATUS_EMOJI[t.status] ?? "•"} ${t.agentTitle} — ${t.status}: ${trunc(t.prompt, 60)}`)
396	            .join("\n")
397	        : "_No tasks yet._";
398	      await interaction.reply({ content: trunc(body, DISCORD_MAX), flags: MessageFlags.Ephemeral });
399	    }
400	  }
401	
402	  async login(): Promise<void> {
403	    await this.client.login(tokenForAgent(this.agent.id));
404	  }
405	}
406	
407	/** Start one Discord bot per agent that has a token configured. Returns the count started. */
408	export function startDiscordFleet(): number {
409	  const agents = getRoster()
410	    .flatMap((p) => p.agents)
411	    .filter((a) => hasToken(a.id));
412	  if (!agents.length) {
413	    console.error(
414	      "No agent has a Discord token configured.\n" +
415	        "Set DISCORD_TOKEN_<AGENT_ID> env vars, or populate code/.data/discord-tokens.json " +
416	        "({ \"project/agent\": \"token\" }). See README — Discord setup."
417	    );
418	    return 0;
419	  }
420	  for (const agent of agents) {
421	    const bot = new AgentBot(agent);
422	    bots.set(agent.id, bot);
423	    bot.login().catch((e) => console.error(`[${agent.id}] login failed:`, e?.message ?? e));
424	  }
425	  console.log(`Starting LifeOS Discord fleet — ${agents.length} agent bot(s) logging in…`);
426	  return agents.length;
427	}
